#!/bin/bash
# The close video's paintings (close-h.html, take a and take b; owner 2026-11-20: "the background needs to be handcrafted").
# Take a: the s2d world (take E's recipe, the chip's ink and light) as a stock exchange hall at the closing bell, plus the bell itself on
# flat blue for key.py, so the bell can ring at the close. Take b: a different painted world, Lower Manhattan at dusk in oil.
# Run: bash w6/ch/gen.sh (the three paintings), bash w6/ch/gen.sh live (the two light loops)   (needs HEDRA_API_KEY; gpt-image-2 medium: about $0.11 at 2K, $0.05 at 1K)
cd /home/user/Tokengame/ez/tools/concepts/launchvid/hedra || exit 1
REF=../../../../media/bet-chip-h2.jpg; GND=img/w6e-ground.jpg
BASE="Painted comic-book illustration in the exact style of the first reference picture: bold black ink outlines, cel shading with rich painted highlights, fine halftone dots in the shadows, one warm golden key light from above, a vivid green rim light along the left edges and a vivid red rim light along the right edges."
NOTXT="No people. No text, no letters, no numbers, no words, no logos, no signs, no screens, no boards, no tickers, no flags."
HALL="$BASE Vertical frame. The great trading hall of a grand old stock exchange at the closing bell, at dusk, empty, seen from the middle of the trading floor looking straight ahead and slightly up. Tall dark fluted marble columns with gilded capitals stand along the far left edge and the far right edge only, receding into darkness. High above, a dark coffered ceiling with faint gold trim fades into black at the top edge. At the top centre, at about 10 percent down, a strong warm golden light source glows as if from a lamp hanging just there, and from it broad warm golden light rays fan downward and outward through thin haze, like the light in the second reference picture. The middle of the frame, from 22 to 88 percent down, is calm open dark space: deep shadow with soft golden haze and the rays only, almost black, no objects in it. At the very bottom a dark polished stone floor with faint golden reflections and a fine halftone texture. A green glow low at the left edge and a red glow low at the right edge. $NOTXT"
BELL="$BASE One large old polished brass ship's-style exchange bell with a thick rim and a small clapper, hanging from a short curved black iron bracket at its top, seen straight on, centred, filling about 60 percent of the frame width and 80 percent of its height, the bracket touching the top of the frame. Warm golden highlights on the brass, ink outlines, halftone in the shadow side, green rim light on its left edge and red rim light on its right edge. The object is isolated on a perfectly flat solid pure blue (#0000FF) background that fills the whole frame edge to edge: no glow, no light rays, no haze, no floor, no cast shadow, crisp clean edges. No people. No text, no letters, no numbers, no words, no logos, no engravings, no symbols."
CITY="Oil painting on canvas with visible thick impasto brushstrokes and palette-knife texture, cinematic and moody, in a limited palette of near-black, deep bottle green, crimson red and warm gold. Vertical frame. Lower Manhattan's financial district at dusk seen from high above, looking down into a deep canyon of old stone skyscrapers. The towers are near-black silhouettes that rise along the far left edge and the far right edge and fill the bottom third of the frame, their many small windows glowing warm gold. Far down at the bottom centre, between the towers, a classical columned exchange building glows gold. The sky fills the upper part of the frame: deep green-black at the top, fading through dark bottle green to a thin band of crimson red and gold dusk light at about 62 percent down, with soft haze drifting between the towers. Calm and empty, no cars. $NOTXT"
J() { python3 -c "import json,sys;print(json.dumps({'prompt':sys.argv[1],'aspect_ratio':sys.argv[2],'resolution':sys.argv[3],'quality':'medium'}))" "$1" "$2" "$3"; }
if [ -z "$1" ]; then
BIG=1 python3 hd.py ch-a-hall gpt-image-2 "$(J "$HALL" 3:4 2K)" "$REF" "$GND" &
python3 hd.py ch-a-bell gpt-image-2 "$(J "$BELL" 1:1 1K)" "$REF" &
BIG=1 python3 hd.py ch-b-city gpt-image-2 "$(J "$CITY" 3:4 2K)" &
wait
fi
# The living light: Kling 2.6 Pro, 5 s, no audio ($0.35 each), from the two grounds (Kling takes 16:9, 9:16 or 1:1 only: 9:16 keeps the full height, the page lays the clip over the middle of the still with feathered sides)
if [ "$1" = live ]; then
python3 hv.py ch-a-hall-live kling-26-pro job_f2bd6384-e701-402d-b4a4-e098c14a1a08 "Locked-off static camera on a tripod: no camera movement, no zoom, no pan. The marble columns, the ceiling and the stone floor stay perfectly still. Only the light is alive: the broad golden light rays from the top slowly shimmer, breathe and sway a little from side to side like light through haze, fine glowing dust motes drift slowly downward through the beams, and the green glow at the lower left and the red glow at the lower right pulse gently. No new objects appear. Painted comic style with ink lines and halftone dots kept exactly. The clip ends as it began." 9:16 &
python3 hv.py ch-b-city-live kling-26-pro job_a7807d0a-308d-48c9-b997-244c7eb4cf09 "Locked-off static camera on a tripod: no camera movement, no zoom, no pan. The buildings stay perfectly still and keep their exact shapes. Only the light and the air are alive: a few small windows flicker warm gold on and off here and there, thin haze drifts slowly sideways between the towers, the crimson and gold dusk glow at the horizon breathes gently, and the dark green clouds in the sky drift very slowly. No new objects appear, no cars, no people. The thick oil-paint brushstroke texture is kept exactly. The clip ends as it began." 9:16 &
wait
fi
